style.css:
@-moz-document url("https://www.google.com/"), url("https://www.google.com/webhp") {
/* Background */
    body {
        background: url('https://macos-wallpapers.com/wp-content/uploads/2023/09/macOS-Sonoma-Light-Wallpaper-6k.jpg') no-repeat center center fixed;
        background-size: cover !important;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif !important;
    }

    /* Google Logo */
    img[alt="Google"] {
        filter: brightness(0) invert(1); /* Makes it white like macOS UI */
    }

    /* Search Box */
    .RNNXgb {
        background: rgba(255, 255, 255, 0.2) !important;
        border-radius: 12px !important;
        backdrop-filter: blur(20px);
        border: 1px solid rgba(255, 255, 255, 0.3);
        transition: all 0.3s ease-in-out;
    }

    /* Search Box Hover & Focus */
    .RNNXgb:hover, .RNNXgb:focus-within {
        background: rgba(255, 255, 255, 0.3) !important;
        border: 1px solid rgba(255, 255, 255, 0.5);
    }

    /* Buttons */
    .FPdoLc input[type="submit"] {
        background: rgba(255, 255, 255, 0.2) !important;
        border-radius: 8px !important;
        backdrop-filter: blur(10px);
        color: white !important;
        border: none;
        padding: 8px 16px;
        font-weight: bold;
        transition: all 0.3s ease-in-out;
    }

    .FPdoLc input[type="submit"]:hover {
        background: rgba(255, 255, 255, 0.3) !important;
    }

    /* Footer Links */
    #fbar {
        background: rgba(0, 0, 0, 0.3) !important;
        color: white !important;
        backdrop-filter: blur(10px);
    }

    /* Links */
    a {
        color: #007AFF !important; /* macOS blue */
    }

    a:hover {
        text-decoration: underline !important;
    }
}
